test "format corpus: one-shot thinking reaches served templates and effort budgets" {
    const a = std.testing.allocator;
    const cli = @import("cli.zig");
    const families = .{
        .{ "qwen4_exp", @embedFile("fixtures/qwen38_chat_template.jinja") },
        .{ "mimo_v2", @embedFile("fixtures/mimo_v26_chat_template.jinja") },
    };
    inline for (families) |family| {
        var choices = std.ArrayList(cli.Think).empty;
        defer choices.deinit(a);
        try choices.appendSlice(a, &.{ .model_default, .on });
        for (model_mod.effortArms(family[0]).?) |arm| try choices.append(a, .{ .effort = arm.effort });
        for (choices.items) |think| {
            const body = try cli.buildPromptBody(a, "  literal prompt\n", think, .{});
            defer a.free(body);
            const parsed = try std.json.parseFromSlice(std.json.Value, a, body, .{});
            defer parsed.deinit();
            const root = parsed.value.object;
            const effort = try parseReasoningEffort(root, 77, false, model_mod.effortArms(family[0]));
            const enable = resolveEnableThinking(root, effort, true);
            try std.testing.expectEqual(think != .effort or think.effort != .off, enable);
            if (think == .effort) {
                try std.testing.expectEqual(@as(i32, switch (think.effort) {
                    .low => 2048,
                    .medium => 8192,
                    else => 77,
                }), effort.?.budget);
            }
            var cc: chat_mod.ChatConfig = .{ .chat_template = family[1], .bos_token = null, .eos_token = null, .add_bos_token = false, .allocator = a };
            const rendered = try chat_mod.renderChatTemplate(a, &.{.{ .role = "user", .content = root.get("messages").?.array.items[0].object.get("content").?.string }}, &cc, null, null, enable, if (effort) |e| e.effort else null, false);
            defer a.free(rendered);
            try std.testing.expect(std.mem.indexOf(u8, rendered, "literal prompt") != null);
            if (std.mem.eql(u8, family[0], "qwen4_exp")) {
                try std.testing.expectEqual(enable, chat_mod.promptTailOpensThink(rendered));
            } else {
                try std.testing.expect(std.mem.endsWith(u8, rendered, if (enable) "<|im_start|>assistant\n" else "<think></think>"));
            }
            if (std.mem.eql(u8, family[0], "qwen4_exp") and think == .effort and think.effort == .xhigh)
                try std.testing.expect(std.mem.indexOf(u8, rendered, "Reasoning effort is set to xhigh.") != null);
        }
    }
}

test "one-shot shutdown closes an unaccepted connection before joining its client" {
    const Waiter = struct {
        fd: std.posix.socket_t,
        disconnected: bool = false,
        fn run(self: *@This()) void {
            var fds = [_]std.posix.pollfd{.{ .fd = self.fd, .events = std.posix.POLL.IN, .revents = 0 }};
            self.disconnected = (std.posix.poll(&fds, 500) catch 0) > 0;
        }
    };
    var listener = try startListener("127.0.0.1", 0);
    const client = try listener.socket.address.connect(std.testing.io, .{ .mode = .stream });
    defer client.close(std.testing.io);
    var waiter: Waiter = .{ .fd = client.socket.handle };
    const thread = try std.Thread.spawn(.{}, Waiter.run, .{&waiter});
    closeEmbeddedListener(std.testing.io, &listener, thread);
    try std.testing.expect(waiter.disconnected);
}

test "liveSessions copies the queue snapshot and stamps the effective context limit" {
    const t = std.testing;
    var sch: scheduler_mod.Scheduler = undefined;
    sch.io = t.io;
    sch.queue_mu = .init;
    sch.live_sessions = undefined;
    sch.live_session_count = 2;
    var row = instr.Session.init("org/live-test", .decode, 1700, 1200, 200, 4096);
    row.request_id = 42;
    row.max_tokens = 32000;
    row.elapsed_seconds = 12.5;
    row.entry_id = 7;
    sch.live_sessions[0] = row;
    sch.live_sessions[1] = instr.Session.init("org/never-loaded", .prefill, 512, 0, 0, 1024);
    sch.digest_mu = .init;
    var restored = instr.Session.init("org/live-test", .cached, 1200, 1200, 0, 2048);
    restored.entry_id = 7;
    var idle = instr.Session.init("org/live-test", .cached, 300, 300, 0, 512);
    idle.entry_id = 9;
    sch.cached_sessions[0] = restored;
    sch.cached_sessions[1] = idle;
    sch.cached_session_count = 2;
    const prev_sch = global_scheduler;
    defer global_scheduler = prev_sch;
    global_scheduler = &sch;

    const reg = try ModelRegistry.init(t.allocator, t.io, null, 1, 0, null);
    defer reg.deinit();
    const lm = try reg.registerStub("org/live-test", "/path/to/m", null);
    var cfg = std.mem.zeroes(model_mod.ModelConfig);
    lm.state = .ready;
    lm.config = &cfg;
    defer lm.config = null; // LoadedModel.deinit destroys a non-null config — detach first
    const prev_ctx = server_config.max_context_size;
    defer server_config.max_context_size = prev_ctx;
    server_config.max_context_size = 8192; // manualContext wins: no GPU sizing

    var buf: [2 * instr.MAX_SESSIONS]instr.Session = undefined;
    const rows = liveSessions(reg, &buf);
    // The entry the decode row restored from is listed once, as that row.
    try t.expectEqual(@as(usize, 3), rows.len);
    try t.expectEqual(instr.Session.Phase.cached, rows[2].phase);
    try t.expectEqual(@as(u32, 300), rows[2].context_tokens);
    try t.expectEqual(@as(u32, 8192), rows[2].context_length);
    try t.expectEqualStrings("org/live-test", rows[0].model());
    try t.expectEqual(@as(u64, 42), rows[0].request_id);
    try t.expectEqual(@as(u32, 32000), rows[0].max_tokens);
    try t.expectEqual(@as(f64, 12.5), rows[0].elapsed_seconds);
    // The ready model's row carries its EFFECTIVE limit (`--ctx-size` ranks
    // above the model default, auto sizing never runs here).
    try t.expectEqual(@as(u32, 8192), rows[0].context_length);
    // An id the registry never resolved keeps 0 = unknown — a placeholder,
    // never a modeled guess — and the queue snapshot itself is untouched:
    // the reader copies, it never mutates the inference thread's rows.
    try t.expectEqual(@as(u32, 0), rows[1].context_length);
    try t.expectEqual(@as(u32, 0), sch.live_sessions[0].context_length);

    // Before `serve()` wires a scheduler: an empty slice, not a crash.
    global_scheduler = null;
    try t.expectEqual(@as(usize, 0), liveSessions(reg, &buf).len);
}

